-- AssetbyNu v1 | Jalankan sekali di Supabase SQL Editor
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null, role text not null check(role in ('admin','inspeksi')), created_at timestamptz default now());
create table if not exists public.gardu (id bigint generated by default as identity primary key, nomor text not null unique, penyulang text, status text not null default 'AKTIF' check(status in ('AKTIF','DIBONGKAR','PERLU_VERIFIKASI')),status_sumber text,alamat text,latitude double precision,longitude double precision,konstruksi text,kondisi_konstruksi text,kapasitas_aset numeric,kapasitas_trafo numeric,merek text,tahun int,nomor_seri text,kondisi_trafo text,kondisi_arrester text,posisi_arrester text,jenis_turunan text,ukuran text,fco text,kondisi_phb text,kantor_pelayanan text,gh_recloser text,panjang_jtr numeric,keterangan text,updated_at timestamptz default now());
create table if not exists public.wo (id bigint generated always as identity primary key,judul text not null,bulan int not null check(bulan between 1 and 12),tahun int not null,petugas uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.wo_gardu (wo_id bigint references public.wo(id) on delete cascade,gardu_id bigint references public.gardu(id) on delete cascade,primary key(wo_id,gardu_id));
create table if not exists public.pengukuran (id bigint generated always as identity primary key,gardu_id bigint not null references public.gardu(id),tahun int not null,semester int not null check(semester in (1,2)),sesi text not null check(sesi in ('SIANG','MALAM')),tanggal date not null default current_date,petugas uuid references public.profiles(id),diinput_oleh uuid references public.profiles(id),data jsonb not null default '{}'::jsonb,catatan text,updated_at timestamptz default now(),unique(gardu_id,tahun,semester,sesi));
create table if not exists public.riwayat (id bigint generated always as identity primary key,gardu_id bigint references public.gardu(id),aksi text not null,alasan text,tanggal_kejadian date not null,detail jsonb default '{}'::jsonb,pelaku uuid references public.profiles(id),created_at timestamptz default now());
create index if not exists gardu_penyulang_idx on public.gardu(penyulang);
create index if not exists ukur_periode_idx on public.pengukuran(tahun,semester,gardu_id);
create index if not exists wo_petugas_idx on public.wo(petugas,tahun,bulan);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create or replace function public.is_inspeksi() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='inspeksi')$$;
create or replace function public.assigned_gardu(g bigint) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.wo w join public.wo_gardu wg on wg.wo_id=w.id where w.petugas=auth.uid() and wg.gardu_id=g)$$;
-- Profil dibuat otomatis setelah akun dibuat di Authentication > Users.
create or replace function public.sync_asset_profile() returns trigger language plpgsql security definer set search_path=public as $$begin if lower(new.email)='admin@asset.spn' then insert into public.profiles(id,username,role) values(new.id,'admin','admin') on conflict(id) do update set username='admin',role='admin'; elsif lower(new.email)='inspeksi@asset.spn' then insert into public.profiles(id,username,role) values(new.id,'inspeksi','inspeksi') on conflict(id) do update set username='inspeksi',role='inspeksi'; end if; return new;end$$;
drop trigger if exists asset_profile_trigger on auth.users;
create trigger asset_profile_trigger after insert or update of email on auth.users for each row execute function public.sync_asset_profile();
insert into public.profiles(id,username,role) select id,case when lower(email)='admin@asset.spn' then 'admin' else 'inspeksi' end,case when lower(email)='admin@asset.spn' then 'admin' else 'inspeksi' end from auth.users where lower(email) in ('admin@asset.spn','inspeksi@asset.spn') on conflict(id) do update set username=excluded.username,role=excluded.role;
alter table public.profiles enable row level security;
alter table public.gardu enable row level security;
alter table public.wo enable row level security;
alter table public.wo_gardu enable row level security;
alter table public.pengukuran enable row level security;
alter table public.riwayat enable row level security;
create policy "profile self or admin" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "gardu read authorized" on public.gardu for select to authenticated using(public.is_admin() or (public.is_inspeksi() and public.assigned_gardu(id)));
create policy "gardu admin insert" on public.gardu for insert to authenticated with check(public.is_admin());
create policy "gardu admin update" on public.gardu for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "wo read" on public.wo for select to authenticated using(public.is_admin() or petugas=auth.uid());
create policy "wo admin insert" on public.wo for insert to authenticated with check(public.is_admin());
create policy "wo admin update" on public.wo for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "wo admin delete" on public.wo for delete to authenticated using(public.is_admin());
create policy "wo_gardu read" on public.wo_gardu for select to authenticated using(public.is_admin() or exists(select 1 from public.wo where id=wo_id and petugas=auth.uid()));
create policy "wo_gardu admin insert" on public.wo_gardu for insert to authenticated with check(public.is_admin());
create policy "wo_gardu admin delete" on public.wo_gardu for delete to authenticated using(public.is_admin());
create policy "ukur read" on public.pengukuran for select to authenticated using(public.is_admin() or (public.is_inspeksi() and public.assigned_gardu(gardu_id)));
create policy "ukur insert" on public.pengukuran for insert to authenticated with check((public.is_admin() or (public.is_inspeksi() and public.assigned_gardu(gardu_id))) and diinput_oleh=auth.uid());
create policy "ukur update" on public.pengukuran for update to authenticated using(public.is_admin() or (public.is_inspeksi() and public.assigned_gardu(gardu_id))) with check((public.is_admin() or (public.is_inspeksi() and public.assigned_gardu(gardu_id))) and diinput_oleh=auth.uid());
create policy "riwayat admin read" on public.riwayat for select to authenticated using(public.is_admin());
create policy "riwayat admin insert" on public.riwayat for insert to authenticated with check(public.is_admin() and pelaku=auth.uid());
-- Atomik: kedua gardu ditukar dalam satu transaksi database, riwayat dicatat.
create or replace function public.rotasi_trafo(a bigint,b bigint,tgl date,alasan_text text) returns void language plpgsql security invoker set search_path=public as $$declare x public.gardu%rowtype;y public.gardu%rowtype;begin
 if not public.is_admin() then raise exception 'Akses ditolak';end if;
 if a=b then raise exception 'Pilih dua gardu berbeda';end if;
 perform 1 from public.gardu where id in (a,b) order by id for update;
 select * into x from public.gardu where id=a;select * into y from public.gardu where id=b;
 if x.id is null or y.id is null then raise exception 'Gardu tidak ditemukan';end if;
 update public.gardu set kapasitas_trafo=y.kapasitas_trafo,merek=y.merek,tahun=y.tahun,nomor_seri=y.nomor_seri,kondisi_trafo=y.kondisi_trafo,updated_at=now() where id=a;
 update public.gardu set kapasitas_trafo=x.kapasitas_trafo,merek=x.merek,tahun=x.tahun,nomor_seri=x.nomor_seri,kondisi_trafo=x.kondisi_trafo,updated_at=now() where id=b;
 insert into public.riwayat(gardu_id,aksi,alasan,tanggal_kejadian,detail,pelaku) values(a,'ROTASI',alasan_text,tgl,jsonb_build_object('dari',x.nomor,'dengan',y.nomor,'trafo_lama',x.nomor_seri,'trafo_baru',y.nomor_seri),auth.uid()),(b,'ROTASI',alasan_text,tgl,jsonb_build_object('dari',y.nomor,'dengan',x.nomor,'trafo_lama',y.nomor_seri,'trafo_baru',x.nomor_seri),auth.uid());end$$;
grant execute on function public.rotasi_trafo(bigint,bigint,date,text) to authenticated;
